function getSubmodelType(submodel){
    if(submodel.meta && submodel.meta.type){
        return submodel.meta.type
    }
    return "sf:"+submodel.id
}

function generateSubmodelConfig(submodel){
    const submodelType = getSubmodelType(submodel)
    const label = submodel.name || submodelType;
    const category = submodel.category || "function";
    const color = submodel.color || "#C0DEED";
    const inputCount = submodel.in?submodel.in.length:0;
    const outputCount = submodel.out?submodel.out.length:0;
    const icon = submodel.icon || "arrow-in.svg";

    const defaults = {
        name: {value: ""}
    }

    const credentials = {}

    
    if (submodel.env) {
        submodel.env.forEach(prop => {
            var defaultValue;

            switch(prop.type) {
                case "cred": defaultValue = ""; break;
                case "str": defaultValue = prop.value||""; break;
                case "bool": defaultValue = (typeof prop.value === 'boolean')?prop.value:prop.value === "true" ; break;
                case "num": defaultValue = (typeof prop.value === 'number')?prop.value:Number(prop.value); break;
                default:
                    defaultValue = {
                        type: prop.type,
                        value: prop.value||""
                    }
            }



            defaults[prop.name] = {
                value: defaultValue,
                ui: prop.ui
            }
            if (prop.type === 'cred') {
                defaults[prop.name].ui.type = "cred";
                credentials[prop.name] = {type:"password"}
            }
        })
    }
    const defaultString = JSON.stringify(defaults);
    const credentialsString = JSON.stringify(credentials);

    let nodeHelp = "";
    if (submodel.info) {
        nodeHelp = `<script type="text/markdown" data-help-name="${submodelType}">${submodel.info}</script>`
    }
    return `<script type="text/javascript">
    RED.nodes.registerType("${submodelType}",{
        submodelModule: true,
        category: "${category}",
        color: "${color}",
        defaults: ${defaultString},
        credentials: ${credentialsString},
        inputs:${inputCount},
        outputs:${outputCount},
        icon: "${icon}",
        paletteLabel: "${label}",
        label: function() {
            return this.name||"${label}";
        },
        labelStyle: function() {
            return this.name?"node_label_italic":"";
        },
        oneditprepare: function() {
            RED.submodel.buildEditForm('submodel', this);
        },
        oneditsave: function() {
            var props = RED.submodel.exportSubmodelInstanceEnv(this);
            var i=0,l=props.length;
            for (;i<l;i++) {
                var prop = props[i];
                if (this._def.defaults[prop.name].ui && this._def.defaults[prop.name].ui.type === "cred") {
                    this[prop.name] = "";
                    this.credentials[prop.name] = prop.value || "";
                    this.credentials['has_' + prop.name] = (this.credentials[prop.name] !== "");
                } else {
                    switch(prop.type) {
                        case "str": this[prop.name] = prop.value||""; break;
                        case "bool": this[prop.name] = (typeof prop.value === 'boolean')?prop.value:prop.value === "true" ; break;
                        case "num": this[prop.name] = (typeof prop.value === 'number')?prop.value:Number(prop.value); break;
                        default:
                            this[prop.name] = {
                                type: prop.type,
                                value: prop.value||""
                            }
                    }
                }
            }
        }
    });
</script>
<script type="text/x-red" data-template-name="${submodelType}">
    <div class="form-row">
        <label for="node-input-name" data-i18n="[append]editor:common.label.name"><i class="fa fa-tag"></i> </label>
        <input type="text" id="node-input-name" data-i18n="[placeholder]editor:common.label.name">
    </div>
    <div id="submodel-input-ui"></div>
</script>
${nodeHelp}
`
}


function register(id,submodel) {
    return {
        submodel: submodel,
        type: getSubmodelType(submodel),
        config: generateSubmodelConfig(submodel)
    }
}

module.exports = {
    register: register
}
    
